// TestQwenReasoningWireChatTemplateKwargsEnvelope verifies that the Qwen wire format
// emits enable_thinking and thinking_budget inside a chat_template_kwargs envelope,
// not at the top level. This is the sindri llama-server fix from the 2026-05-11 probe:
// top-level enable_thinking/thinking_budget are silently dropped by llama-server,
// but the chat_template_kwargs envelope activates thinking (250-526 completion tokens
// with extracted reasoning_content).
func TestQwenReasoningWireChatTemplateKwargsEnvelope(t *testing.T) {
	const model = "Qwen3.6-27B-UD-Q3_K_XL.gguf"

	t.Run("on/emits chat_template_kwargs envelope", func(t *testing.T) {
		body, err := captureOpenAIChatBodyWithReasoningWireQwen(t, model, nil, nil, agent.Options{Reasoning: agent.ReasoningTokens(4096)})
		require.NoError(t, err)
		assertQwenReasoningWireBudget(t, body, true, 4096)
	})

	t.Run("off/emits chat_template_kwargs.enable_thinking=false", func(t *testing.T) {
		body, err := captureOpenAIChatBodyWithReasoningWireQwen(t, model, nil, nil, agent.Options{Reasoning: agent.ReasoningOff})
		require.NoError(t, err)
		assertQwenReasoningWireBudget(t, body, false, 0)
	})
}

// TestOpenAIEffortReasoningWire verifies the flat top-level reasoning_effort wire
// emitted by OpenAIEffort-format providers (ds4 / deepseek-v4-flash).
func TestOpenAIEffortReasoningWire(t *testing.T) {
	const model = "deepseek-v4-flash"

	t.Run("high/emits reasoning_effort:high", func(t *testing.T) {
		body, err := captureOpenAIChatBodyWithOpenAIEffort(t, model, nil, agent.Options{Reasoning: agent.ReasoningHigh})
		require.NoError(t, err)
		assertOpenAIEffortReasoningWire(t, body, "high")
	})

	t.Run("low/emits reasoning_effort:high via alias map", func(t *testing.T) {
		body, err := captureOpenAIChatBodyWithOpenAIEffort(t, model, nil, agent.Options{Reasoning: agent.ReasoningLow})
		require.NoError(t, err)
		assertOpenAIEffortReasoningWire(t, body, "high")
	})

	t.Run("off/emits think:false", func(t *testing.T) {
		body, err := captureOpenAIChatBodyWithOpenAIEffort(t, model, nil, agent.Options{Reasoning: agent.ReasoningOff})
		require.NoError(t, err)
		assertOpenAIEffortOffWire(t, body)
	})

	t.Run("tokens=4096/snaps to high via alias map", func(t *testing.T) {
		body, err := captureOpenAIChatBodyWithOpenAIEffort(t, model, nil, agent.Options{Reasoning: agent.ReasoningTokens(4096)})
		require.NoError(t, err)
		assertOpenAIEffortReasoningWire(t, body, "high")
	})
}

func TestOpenAIEffortReasoningWireAliasMapWarning(t *testing.T) {
	const model = "deepseek-v4-flash"
	logHandler := &testLogHandler{}
	logger := slog.New(logHandler)

	body, err := captureOpenAIChatBodyWithOpenAIEffort(t, model, logger, agent.Options{Reasoning: agent.ReasoningLow})
	require.NoError(t, err)
	assertOpenAIEffortReasoningWire(t, body, "high")

	msgs := logHandler.Messages()
	require.NotEmpty(t, msgs, "expected a structured warning log for ds4 alias map")
	assert.Contains(t, msgs[0], "reasoning alias map overrode requested tier")
	assert.True(t, logHandler.HasAttr("reasoning_emitted_reason", "ds4 alias map"))
	assert.True(t, logHandler.HasAttr("reasoning_emitted", "high"))
}

func TestOpenAIEffortReasoningWireEmittedTelemetry(t *testing.T) {
	const model = "deepseek-v4-flash"
	var bodyMu sync.Mutex
	var capturedBody []byte
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		bodyMu.Lock()
		capturedBody = append([]byte(nil), body...)
		bodyMu.Unlock()
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{
			"id":"chatcmpl-1",
			"model":"` + model + `",
			"choices":[{"index":0,"message":{"role":"assistant","content":"done"},"finish_reason":"stop"}],
			"usage":{"prompt_tokens":12,"completion_tokens":5,"total_tokens":17}
		}`))
	}))
	defer srv.Close()

	caps := openai.OpenAIProtocolCapabilities
	caps.Thinking = true
	caps.ThinkingFormat = openai.ThinkingWireFormatOpenAIEffort
	caps.ReasoningAliasMap = map[string]string{
		"low":    "high",
		"medium": "high",
		"xhigh":  "high",
	}
	caps.SupportedRequestParams = []string{"reasoning_effort", "think"}

	p := openai.New(openai.Config{
		BaseURL:        srv.URL + "/v1",
		APIKey:         "test",
		Model:          model,
		ProviderSystem: "ds4",
		Capabilities:   &caps,
	})

	resp, err := p.Chat(context.Background(), []agent.Message{{Role: agent.RoleUser, Content: "hello"}}, nil, agent.Options{Reasoning: agent.ReasoningLow})
	require.NoError(t, err)
	bodyMu.Lock()
	defer bodyMu.Unlock()
	assert.Contains(t, string(capturedBody), `"reasoning_effort":"high"`)
	require.NotNil(t, resp.Attempt)
	assert.Equal(t, string(agent.ReasoningHigh), resp.Attempt.ReasoningEmitted)
}

